import { Progress as BaseProgress } from '@base-ui/react/progress';
import type { ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { progressVariants, type ProgressVariantProps } from './progress.variants';

export interface ProgressProps extends Omit<BaseProgress.Root.Props, 'className' | 'children'>, ProgressVariantProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Visible label; also the accessible name. Without it, pass `aria-label`. */
  label?: ReactNode;
  /** Shows the formatted value (e.g. "72%") opposite the label. */
  showValue?: boolean;
}

/**
 * Task progress bar (role="progressbar") on Base UI Progress. `value={null}` makes it
 * indeterminate: a pulsing segment that holds still under reduced motion.
 */
export function Progress({ tone, size, label, showValue = false, className, ...props }: ProgressProps) {
  const s = progressVariants({ tone, size });
  const indeterminate = props.value == null;
  return (
    <BaseProgress.Root className={cn(s.root(), className)} {...props}>
      {(label != null || (showValue && !indeterminate)) && (
        <div className={s.header()}>
          {label != null ? <BaseProgress.Label className={s.label()}>{label}</BaseProgress.Label> : <span />}
          {showValue && !indeterminate && <BaseProgress.Value className={s.value()} />}
        </div>
      )}
      <BaseProgress.Track className={s.track()}>
        <BaseProgress.Indicator className={s.indicator()} />
      </BaseProgress.Track>
    </BaseProgress.Root>
  );
}

export { Progress, type ProgressProps } from './Progress';
export { progressVariants, type ProgressVariantProps } from './progress.variants';
export { doc as progressDoc } from './Progress.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const progressVariants = tv({
  slots: {
    root: 'grid w-full gap-1.5',
    header: 'flex items-center justify-between gap-3',
    label: 'text-[12.5px] font-medium text-foreground',
    value: 'font-mono text-[11.5px] font-semibold tabular-nums',
    track: 'relative w-full overflow-hidden rounded-full bg-secondary',
    indicator: [
      'block h-full rounded-full transition-[width] duration-400 ease-out motion-reduce:transition-none',
      'data-[indeterminate]:w-2/5 data-[indeterminate]:animate-pulse motion-reduce:data-[indeterminate]:animate-none',
    ],
  },
  variants: {
    tone: {
      primary: { indicator: 'bg-primary', value: 'text-foreground' },
      success: { indicator: 'bg-success', value: 'text-success-text' },
      warning: { indicator: 'bg-warning', value: 'text-warning-text' },
      destructive: { indicator: 'bg-destructive', value: 'text-destructive-text' },
    },
    size: {
      sm: { track: 'h-1.5' },
      md: { track: 'h-2' },
      lg: { track: 'h-2.5' },
    },
  },
  defaultVariants: { tone: 'primary', size: 'md' },
});

export type ProgressVariantProps = VariantProps<typeof progressVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Progress',
  group: 'Feedback',
  status: 'stable',
  description: 'Progress bar for a running task: optional label and formatted value, four tones (primary, success, warning, destructive), three heights, and an indeterminate state (value null) that stops pulsing under reduced motion.',
  primitive: '@base-ui/react/progress',
  pattern: 'progressbar',
  tokens: ['primary', 'success', 'success-text', 'warning', 'warning-text', 'destructive', 'destructive-text', 'secondary', 'foreground'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
